55	const PROCESSING_FEE = 5;
56	
57	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	} as const satisfies Record<string, number>;
67	
68	type InsurableItemType = keyof typeof BASE_PREMIUMS;
69	
70	const isInsurableItemType = (type: string): type is InsurableItemType =>
71	  type in BASE_PREMIUMS;
72	
73	const basePremiumForItem = (item: Item): number => {
74	  if (!isInsurableItemType(item.type)) return 0;
75	  return BASE_PREMIUMS[item.type];
76	};
77	
78	const basePremiumForItems = (items: Item[]): number =>
79	  items.reduce((sum, item) => sum + basePremiumForItem(item), 0);
80	
81	const withInitialAssessmentSurcharge = (basePremium: number): number =>
82	  basePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE);
83	
84	const quotePremium = (items: Item[]): number =>
85	  Math.round(
86	    withInitialAssessmentSurcharge(basePremiumForItems(items)) + PROCESSING_FEE,
87	  );
88	
89	const runStep = (step: Step): StepResult => {
90	  if (step.op === "quote") return { premium: quotePremium(step.items) };
91	  throw new Error(`Unsupported step: ${step.op}`);
92	};
93	
94	export const runScenario = (scenario: Scenario): ScenarioResult => ({
95	  results: scenario.steps.map(runStep),
96	});
