// Unknown item types are not yet rejected — the spec requires an error, but no
// test drives that behaviour yet, so they are priced at 0 for the moment.
const UNPRICED_UNKNOWN_TYPE = 0;

const basePremiumForItem = (item: Item): number =>
  isInsurableItemType(item.type)
    ? BASE_PREMIUMS[item.type]
    : UNPRICED_UNKNOWN_TYPE;
